from typing import List

class Solution:
    def maxSatisfied(self, customers: List[int], grumpy: List[int], minutes: int) -> int:
        best = 0
        n = len(customers)
        for start in range(n - minutes + 1):
            total = 0
            for i in range(n):
                if grumpy[i] == 0 or start <= i < start + minutes:
                    total += customers[i]
            best = max(best, total)
        return best

